def verify_password(plain_password, stored_hash):
    return pbkdf2_hmac('sha256', plain_password.encode(), salt, rounds) == stored_hash

def hash_password(password):
    return create_salted_pbkdf2_hash(password)

def create_access_token(user_id):
    return jwt.encode({'sub': str(user_id), 'exp': expires_at}, SECRET_KEY)

def decode_access_token(token):
    return jwt.decode(token, SECRET_KEY, algorithms=['HS256'])

def safe_archive_path(name):
    path = PurePosixPath(name)
    return not path.is_absolute() and '..' not in path.parts

def ingest_zip(upload):
    enforce_file_count_and_expanded_size_limits(upload)

def retrieve(question):
    lexical = keyword_search(question)
    semantic = pgvector_cosine_search(question)
    return reciprocal_rank_fusion(lexical, semantic)
